.avatar-url-display {
    font-size: 0.8rem;
    color: #888;
    word-break: break-all;
}

/* Toggles */
.toggle-group {
    margin-bottom: 1rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

.toggle-label input[type="checkbox"] {
    width: 18px;
    height: 18px;
}

